import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.CD3qHYUq.js";var i=JSON.parse(`{"title":"Telemetry","description":"Enabling Telemetry for your BullMQ based applications","frontmatter":{"description":"Enabling Telemetry for your BullMQ based applications"},"headers":[],"relativePath":"guide/telemetry/index.md","filePath":"guide/telemetry/README.md","lastUpdated":1791878763000}`),a={name:`guide/telemetry/index.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="telemetry" tabindex="-1">Telemetry <a class="header-anchor" href="#telemetry" aria-label="Permalink to “Telemetry”">​</a></h1><p>BullMQ provides a Telemetry interface that can be used to integrate it with any external telemetry backends. Currently we support the <a href="https://opentelemetry.io" target="_blank" rel="noreferrer">OpenTelemetry</a> specification, which is the new de-facto standard for telemetry purposes, however the interface if flexible enough to support any other backends in the future.</p><p>Telemetry is very useful for large applications where you want to get a detailed and general overview of the system. For BullMQ it helps to gain insight in the different statuses a job may be during its complete lifecycle. In a large application it helpts tracking the source of the jobs and all the interactions the jobs or messages may perform with other parts of the system.</p><h2 id="read-more" tabindex="-1">Read more: <a class="header-anchor" href="#read-more" aria-label="Permalink to “Read more:”">​</a></h2><ul><li>💡 <a href="https://bullmq.io/articles/guides/monitoring-bullmq-queues/" target="_blank" rel="noreferrer">How to monitor and manage BullMQ queues</a>, an overview of dashboards, metrics and alerts for BullMQ</li></ul>`,5)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};